export const getUpdatePostUrl = (id: string,
    params?: UpdatePostParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : String(value))
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/v1/posts/${id}?${stringifiedParams}` : `/v1/posts/${id}`
}

/**
 * Changes fields. A scheduled or published post is re-validated and re-rendered; an invalid change is refused. With autosave=true, the saves of one writing session (same author, up to ten minutes) share one revision. Tokens change drafts only (403 live_post).
 */
export const updatePost = async (id: string,
    updatePostBody: UpdatePostBody,
    params?: UpdatePostParams, options?: Parameters<typeof cmsFetch>[1]): Promise<updatePostResponse> => {

  return cmsFetch<updatePostResponse>(getUpdatePostUrl(id,params),
  {
    ...options,
    method: 'PATCH',
    headers: getHeaders({ 'Content-Type': 'application/json' }, options?.headers),
    body: JSON.stringify(updatePostBody)
  }
);}



